#[derive(Debug, Clone, PartialEq, Eq)]
pub struct GeneratedBuiltinManifest {
    pub source_tree_digest: String,
    pub generator_digest: String,
    pub device_count: usize,
}

pub fn render_generated_builtin_manifest(manifest: &GeneratedBuiltinManifest) -> String {
    format!(
        "# Generated by RSpice Verilog-A built-in generation. Do not edit.\nsource_tree_digest={}\ngenerator_digest={}\ndevice_count={}\n",
        manifest.source_tree_digest, manifest.generator_digest, manifest.device_count
    )
}

pub fn parse_generated_builtin_manifest(text: &str) -> Option<GeneratedBuiltinManifest> {
    let mut source_tree_digest = None;
    let mut generator_digest = None;
    let mut device_count = None;

    for line in text.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let (key, value) = line.split_once('=')?;
        match key {
            "source_tree_digest" => source_tree_digest = Some(value.to_string()),
            "generator_digest" => generator_digest = Some(value.to_string()),
            "device_count" => device_count = Some(value.parse().ok()?),
            _ => {}
        }
    }

    Some(GeneratedBuiltinManifest {
        source_tree_digest: source_tree_digest?,
        generator_digest: generator_digest?,
        device_count: device_count?,
    })
}
